schemes = [
    {"name":"PM-KISAN Samman Nidhi","category":"farmer","icon":"🌾","description":"Income support for eligible landholding farmer families.","benefits":"Eligible farmer families receive ₹6,000 per year in three instalments, subject to scheme rules.","eligibility":"Eligible landholding farmer families, subject to institutional landholder and other exclusion rules. e-KYC and land record requirements apply.","documents":"Aadhaar, bank account details, mobile number and land records as required.","application":"Check status and apply through the official PM-KISAN portal or a designated CSC. Complete e-KYC where required."},
    {"name":"Pradhan Mantri Fasal Bima Yojana","category":"farmer","icon":"🌱","description":"Crop insurance support against notified crop losses and risks.","benefits":"Insurance protection for notified crops against specified natural risks, subject to policy terms and notified areas.","eligibility":"Farmers growing notified crops in notified areas during the relevant season, including eligible loanee and non-loanee farmers under current rules.","documents":"Aadhaar, bank details, land or cultivation records, sowing details and crop information.","application":"Apply within the season deadline through the official crop insurance portal, bank, insurer or authorized channel."},
    {"name":"Kisan Credit Card (KCC)","category":"farmer","icon":"💳","description":"Timely credit support for agriculture and allied activities.","benefits":"Access to eligible short-term credit for crop cultivation and certain allied activities at applicable lending terms.","eligibility":"Farmers, tenant farmers, sharecroppers and eligible joint liability groups, subject to lender assessment and scheme rules.","documents":"Identity and address proof, land or cultivation documents, crop details and bank-required forms.","application":"Contact a participating bank or cooperative institution and request a Kisan Credit Card application."},
    {"name":"Soil Health Card Scheme","category":"farmer","icon":"🧪","description":"Soil testing and nutrient recommendations for better farm decisions.","benefits":"Soil test information and recommendations on nutrient use for improved soil management.","eligibility":"Farmers can access soil testing services in participating areas through the scheme's soil testing network.","documents":"Basic farmer and land or plot details may be requested by the local agriculture office.","application":"Contact the local agriculture department or soil testing laboratory for sampling and Soil Health Card information."},
    {"name":"PM Krishi Sinchayee Yojana","category":"farmer","icon":"💧","description":"Promotes improved irrigation access and water-use efficiency.","benefits":"Support for eligible irrigation and water-use interventions under applicable components and state plans.","eligibility":"Depends on the component, location, beneficiary category and current state implementation guidelines.","documents":"Identity, land details, bank information and component-specific documents.","application":"Check current component availability with the state agriculture or irrigation department before applying."},
    {"name":"Ayushman Bharat – PM-JAY","category":"health","icon":"🩺","description":"Hospitalisation cover for eligible beneficiary families.","benefits":"Cashless secondary and tertiary hospitalisation cover up to ₹5 lakh per eligible family per year at empanelled hospitals, subject to package rules.","eligibility":"Eligibility is based on the applicable beneficiary database and current government expansion rules. Check your name before relying on coverage.","documents":"Beneficiary identification and Aadhaar or other accepted identity proof as required at the help desk.","application":"Check eligibility using the official beneficiary portal or helpline and visit an empanelled hospital or Ayushman help desk."},
    {"name":"Pradhan Mantri Awas Yojana – Gramin","category":"housing","icon":"🏡","description":"Rural housing assistance for eligible households without adequate housing.","benefits":"Financial assistance for construction of a pucca house, with amounts and linked support governed by current rural guidelines and location.","eligibility":"Rural households identified and verified under applicable deprivation and inclusion criteria and current programme rules.","documents":"Identity details, bank account, job card or other local records where applicable, land/site details and verification documents.","application":"Contact the Gram Panchayat or Block Development Office to check the beneficiary list and current process."},
    {"name":"Pradhan Mantri Awas Yojana – Urban 2.0","category":"housing","icon":"🏙️","description":"Housing support for eligible urban families under PMAY-U 2.0 components.","benefits":"Assistance through applicable PMAY-U 2.0 verticals, subject to income, house ownership, location and component conditions.","eligibility":"Urban eligible families in specified income groups who meet current component conditions and other exclusions.","documents":"Aadhaar, income proof, address proof, bank details and land or property documents where relevant.","application":"Check the current PMAY-U 2.0 guidelines and apply through the official portal or designated urban local body."},
    {"name":"Pradhan Mantri Ujjwala Yojana","category":"women","icon":"🔥","description":"LPG connection support for eligible women from qualifying households.","benefits":"Deposit-free LPG connection support under current scheme conditions; refill subsidy, if applicable, is governed by current notifications.","eligibility":"Adult women from qualifying poor households without an existing LPG connection in the household, subject to current criteria.","documents":"Aadhaar, ration card or family composition proof, address details, bank account and declaration as required.","application":"Apply through an LPG distributor or the official Ujjwala portal using the current application process."},
    {"name":"Sukanya Samriddhi Yojana","category":"women","icon":"👧","description":"Small-savings account designed for the future of a girl child.","benefits":"Government-notified interest on eligible deposits and tax treatment under prevailing rules.","eligibility":"A guardian may open an account for a girl child who meets the age and account conditions under the scheme.","documents":"Girl child's birth certificate, guardian identity and address proof, photographs and initial deposit.","application":"Open an account at an authorized post office or participating bank. Check current deposit and interest rules."},
    {"name":"Pradhan Mantri Matru Vandana Yojana","category":"women","icon":"🤱","description":"Maternity benefit support for eligible pregnant and lactating women.","benefits":"Conditional maternity benefit assistance as defined under current PMMVY rules and eligible pregnancy categories.","eligibility":"Eligible pregnant and lactating women who meet current exclusions and registration conditions; rules differ by benefit category.","documents":"Aadhaar or accepted identity, MCP/RCH card, bank or post office account and required declarations.","application":"Register through the local Anganwadi centre or approved health facility and follow the current PMMVY process."},
    {"name":"Janani Suraksha Yojana","category":"health","icon":"🏥","description":"Promotes institutional delivery among eligible pregnant women.","benefits":"Cash assistance for eligible women according to state category and current programme guidelines.","eligibility":"Pregnant women meeting the scheme's state, category and institutional-delivery conditions.","documents":"MCP card, identity proof, bank details and documents requested by the health facility.","application":"Contact an ASHA worker, ANM or government health facility before delivery for registration and guidance."},
    {"name":"National Scholarship Portal","category":"education","icon":"🎓","description":"A single digital platform for multiple central and participating scholarship schemes.","benefits":"Scholarship assistance varies by scheme, course, level and beneficiary category.","eligibility":"Depends on the specific scholarship, academic level, income limit, category and institution conditions.","documents":"Student identity, previous marksheets, income/caste/disability certificates where applicable, bank details and institute information.","application":"Register on the National Scholarship Portal, check the scheme-specific notice and submit before its deadline."},
    {"name":"PM POSHAN","category":"education","icon":"🍲","description":"School meal programme supporting nutrition among eligible schoolchildren.","benefits":"Hot cooked meals on school days in covered government and government-aided schools as per programme norms.","eligibility":"Children enrolled in eligible classes and schools covered by the programme.","documents":"No separate public application is usually required; school enrolment and attendance processes apply.","application":"Contact the school head teacher for local implementation, meal schedule and grievance support."},
    {"name":"PM Vishwakarma","category":"finance","icon":"🛠️","description":"Support for traditional artisans and craftspeople in notified trades.","benefits":"Recognition, skill training, toolkit incentive and collateral-free credit support as per current scheme rules.","eligibility":"Self-employed artisans and craftspeople working with hands and tools in notified traditional trades, subject to age and family/exclusion conditions.","documents":"Aadhaar, mobile number, bank details and other details requested during verification.","application":"Register through the official PM Vishwakarma portal with help from a CSC; local verification is part of the process."},
    {"name":"Atal Pension Yojana","category":"finance","icon":"👴","description":"A voluntary pension scheme for eligible subscribers in the unorganised sector.","benefits":"Guaranteed minimum monthly pension options after age 60, based on contribution and selected pension slab, subject to scheme rules.","eligibility":"Indian citizens in the specified joining age range with an eligible savings bank or post office account; income-taxpayer restrictions apply under current rules.","documents":"Savings account, Aadhaar and mobile details as requested by the bank or post office.","application":"Enrol through a participating bank or post office and review the contribution chart before joining."},
    {"name":"Pradhan Mantri Jeevan Jyoti Bima Yojana","category":"finance","icon":"🛡️","description":"Low-cost renewable life insurance cover through participating banks and post offices.","benefits":"Life insurance cover of ₹2 lakh for death due to any cause during the cover period, subject to policy terms and current premium.","eligibility":"Eligible bank or post office account holders in the notified entry age range who provide consent and meet scheme conditions.","documents":"Savings account details, consent/auto-debit mandate and KYC as required by the bank.","application":"Enrol through your participating bank or post office and review exclusions, premium and renewal terms."},
    {"name":"Pradhan Mantri Suraksha Bima Yojana","category":"finance","icon":"🚑","description":"Accident insurance cover through participating banks and post offices.","benefits":"Accident-related death and disability cover under the scheme's notified benefit structure and terms.","eligibility":"Eligible account holders in the notified age range who consent to annual premium auto-debit.","documents":"Savings account details, consent/auto-debit mandate and KYC as required.","application":"Enrol through a participating bank or post office; check current premium and coverage conditions."},
    {"name":"Pradhan Mantri Shram Yogi Maandhan","category":"finance","icon":"👷","description":"Contributory pension support for eligible unorganised workers.","benefits":"Assured monthly pension after age 60 for eligible subscribers who make required contributions, under scheme rules.","eligibility":"Eligible unorganised workers in the specified joining age and monthly income range who are not covered by exclusions.","documents":"Aadhaar, savings bank account and mobile number.","application":"Visit a Common Service Centre for enrolment and contribution details."},
    {"name":"PM SVANidhi","category":"finance","icon":"🛍️","description":"Working-capital loan support for eligible street vendors.","benefits":"Collateral-free working-capital loan tranches and incentives as defined by current programme guidelines and lender terms.","eligibility":"Street vendors meeting the scheme's vending, certificate or local verification requirements.","documents":"Certificate of Vending or Letter of Recommendation, identity and bank details as required.","application":"Apply through the official PM SVANidhi portal or a participating lending institution/urban local body."},
    {"name":"DAY-NULM","category":"finance","icon":"🤝","description":"Livelihood and self-employment support for eligible urban poor households.","benefits":"Support through skill training, self-employment and urban livelihoods components as locally implemented.","eligibility":"Urban poor individuals and groups meeting the relevant component and local implementation criteria.","documents":"Identity, residence, income or group details and bank documents as requested by the urban local body.","application":"Contact the Urban Local Body or City Mission Management Unit for active components and application steps."},
    {"name":"National Means-cum-Merit Scholarship Scheme","category":"education","icon":"📚","description":"Scholarship support to help meritorious students continue secondary education.","benefits":"Annual scholarship support for selected students, subject to current scheme rules and renewal conditions.","eligibility":"Students meeting class, school, examination, income and other current eligibility criteria.","documents":"Previous class marksheet, income certificate, bank account, Aadhaar and school verification details.","application":"Check the current NMMS notification and apply through the National Scholarship Portal within the deadline."},
    {"name":"Post-Matric Scholarship for SC Students","category":"education","icon":"📖","description":"Financial assistance for eligible SC students studying after matriculation.","benefits":"Eligible academic and maintenance support as defined by central and state rules.","eligibility":"SC students meeting the current income ceiling, course and institution conditions.","documents":"Caste certificate, income certificate, marksheets, fee receipt, bank details and Aadhaar as required.","application":"Apply through the relevant state scholarship portal or National Scholarship Portal as notified for the academic year."},
    {"name":"PM Street Vendor's AtmaNirbhar Nidhi (PM SVANidhi) – Interest Support","category":"finance","icon":"🏪","description":"Incentives linked to timely repayment of eligible street-vendor loans.","benefits":"Interest subsidy and digital transaction incentives where available under current programme rules.","eligibility":"Eligible PM SVANidhi borrowers meeting repayment and digital transaction conditions.","documents":"Loan account and bank details, vendor identification and transaction records where applicable.","application":"Ask the participating lender or urban local body about current incentives and claim process."},
]
